import pandas as pd,numpy as np,re
from sklearn.metrics.pairwise import cosine_similarity
tr=pd.read_csv('b3_supercon_train.csv');p=pd.read_csv('b3_supercon_pool.csv')
syms=sorted(set(re.findall(r'[A-Z][a-z]?', ''.join(tr.composition.tolist()+p.composition.tolist()))))
def parse(s):
 d={}
 for e,n in re.findall(r'([A-Z][a-z]?)([0-9]*\.?[0-9]*)',s): d[e]=d.get(e,0)+float(n or 1)
 return d
def vec(s,ignoreO=False):
 d=parse(s)
 if ignoreO:d.pop('O',None)
 z=np.array([d.get(x,0) for x in syms]); return z/z.sum()
for cid in ['c029','c034','c097','c084','c072','c081','c046','c044','c076']:
 q=p[p.candidate_id==cid].iloc[0]
 print('\n',cid,q.composition)
 for io in [False,True]:
  a=np.array([vec(x,io) for x in tr.composition]); b=vec(q.composition,io)
  # L1 and cosine
  dist=np.abs(a-b).sum(1)
  ids=np.argsort(dist)[:6]
  print('noO' if io else 'all')
  for i in ids: print(round(dist[i],3),tr.iloc[i].target,tr.iloc[i].composition)

